function compactGauge(label,value,p,index,color='#a0f7da'){return `<button class="compact-gauge" onclick="kpiDetail(${index})" aria-label="${label}: ${value}"><span class="mini-ring" style="--fill:${p}%;--ring:${color}"><b>${value}</b></span><small>${label}</small></button>`}
function compactPanel(title,value,body,extra=''){return `<section class="panel compact-panel ${extra}"><div class="compact-heading"><h2>${title}</h2>${value?`<strong>${value}</strong>`:''}</div>${body}</section>`}
function unwrapKpiChart(index){const chart=kpiChart(importantKpis[index]);return chart.slice(chart.indexOf('<svg'),chart.indexOf('</svg>')+6)}
businessKpiView=function(){return `<div class="kpi-board" aria-label="Business KPI monitoring board">
${compactPanel('Quality','98.2%',`<div class="quality-combo">${compactGauge('Overall quality','98.2%',98.2,0)}<div>${unwrapKpiChart(0)}</div></div>`)}
${compactPanel('Customer satisfaction','92%',`<div class="customer-combo">${compactGauge('Overall score','92%',92,1)}<div class="sentiment-grid">${[['Dissatisfied','8%','#f5a5ce'],['Neutral','14%','#ffd09d'],['Satisfied','42%','#a9ccff'],['Very satisfied','36%','#a0f7da']].map(r=>`<button onclick="chartPoint('Customer satisfaction','${r[0]}',${parseInt(r[1])},'%')"><span style="color:${r[2]}">●</span><strong>${r[1]}</strong><small>${r[0]}</small></button>`).join('')}</div></div>`)}
${compactPanel('Top 7 product ratings','4.7 / 5',`<div class="product-ratings">${['API','Vaccine','Medical devices','Formulation','WIP','Utility','Warehouse'].map((t,i)=>`<button onclick="chartPoint('Product rating','${t}',${[4.8,4.7,4.9,4.6,4.5,4.8,4.6][i]},'/ 5')"><small>${t}</small><span class="rating-star">★</span><strong>${[4.8,4.7,4.9,4.6,4.5,4.8,4.6][i]}</strong><small>${[650,1980,4560,1771,3590,940,1220][i].toLocaleString()} reviews</small></button>`).join('')}</div>`,'ratings-panel')}
${compactPanel('Compliance with regulatory standards','',`<div class="regulatory-gauges">${compactGauge('Compliance','96%',96,3)}${compactGauge('Recall rate','0.1%',.1,4,'#a9ccff')}${compactGauge('Legal issues','2 open',100,5,'#ffd09d')}</div>`)}
${compactPanel('Delivery status','95.4%',`<div class="delivery-combo">${compactGauge('On time','95.4%',95.4,6)}<div class="delivery-details"><button onclick="kpiDetail(6)"><small>On-time orders</small><strong class="positive">477</strong></button><button onclick="kpiDetail(6)"><small>Late orders</small><strong class="warning">23</strong></button></div></div>`)}
${compactPanel('Top 5 warranty claim products','14 claims',unwrapKpiChart(7))}
${compactPanel('Consumer complaints','29 cases',`<div class="complaint-map">${[['Customer service',3],['Product',9],['Delivery',7],['Quality',6],['Support',4]].map((r,i)=>`<button style="background:${['#236c88','#367184','#378c95','#276b7d','#284d70'][i]}" onclick="chartPoint('Consumer complaints','${r[0]}',${r[1]},'cases')"><span>${r[0]}</span><strong>${r[1]}</strong></button>`).join('')}</div>`)}
${compactPanel('Supplier defect rate','1.9%',unwrapKpiChart(9))}
${compactPanel('Defect rate','1.8%',unwrapKpiChart(10))}
${compactPanel('Cost of poor quality','EGP 32k',unwrapKpiChart(11))}
${compactPanel('Top 5 downtime causes','3.9 h',unwrapKpiChart(12),'downtime-panel')}
</div><div class="compact-board-note"><span>Illustrative snapshot · All measures from your KPI reference · Select a chart or reading for details</span><button onclick="go('Quality')">CIP &amp; PAT quality monitoring →</button></div>`};
